/**
 * Debug HUD overlay: FPS, JS heap vs the resident-memory
 * budget, engine path, key adapter limits with clamp flagging.
 *
 * CODE-SPLIT dev tooling: loaded via dynamic `import()` from main.ts only
 * when toggled on (Backquote hotkey) or when `?debug=1` is present. A
 * session that never toggles never fetches this chunk — it contributes ZERO
 * main-bundle bytes. DOM-only: NO `@babylonjs/*` imports (pinned by
 * the requirements tier); the only crossing to the main graph is a TYPE-only
 * import (erased at compile time).
 *
 * The HUD owns no engine reference: main.ts hands it a `getSample()` closure
 * and the HUD renders whatever it is handed, refreshing on its own interval
 * (HUD_UPDATE_INTERVAL_MS). Each refresh increments the container's
 * `data-webverse-hud-updates` attribute — the e2e's deterministic
 * "updating live" assert (FPS text alone can plateau at a stable 60.0).
 *
 * The overlay attaches to `document.body`, NOT the canvas (the WebGPU→WebGL2
 * fallback may replace the canvas element), is `pointer-events: none` (it
 * can never eat canvas input) and `aria-hidden` (a dev-only visual).
 * `dispose()` clears the interval and removes the node; idempotent — a leaked
 * interval touching removed DOM is the failure it guards against.
 */
import type { ResolvedDeviceCaps, ResolvedLimit } from '../engine/deviceCaps';
// TYPE-ONLY import (erased at compile time) — keeps the HUD chunk DOM-only and
// @babylonjs-free. capabilityRegistry.ts is pure data (zero Babylon), so this
// is safe. The capability report DATA lives in main-bundle session
// state; only its DISPLAY is here in the code-split HUD chunk.
import type { CapabilityReport } from '../capabilities/capabilityRegistry';

/**
 * Resident-memory budget for the tight tiers (mobile/Quest), surfaced in the
 * debug HUD. A browser policy constant; tune when real device profiling lands.
 */
export const RESIDENT_MEMORY_BUDGET_MB = 512;

/** HUD refresh cadence — fast enough to read as live, cheap enough to ignore. */
export const HUD_UPDATE_INTERVAL_MS = 250;

/**
 * Clamp markers say what effective actually landed on. HUD_CLAMP_MARKER —
 * the device reported BELOW the portable floor and effective was RAISED to
 * the floor (the headline case; the e2e asserts it under `limits=low`). HUD_CLAMP_MARKER_DEVICE — the
 * device sits between floor and configured, so the configured ceiling was
 * clamped down TO the device's own actual (effective = actual).
 */
export const HUD_CLAMP_MARKER = 'CLAMPED→floor';
export const HUD_CLAMP_MARKER_DEVICE = 'CLAMPED→device';

/**
 * Banners (the HUD flags the clamp): floor variant when ANY key
 * resolved at the portable floor above the device report (override /
 * out-of-spec device); device variant when keys are merely held below the
 * configured ceilings at the device's own limits.
 */
export const HUD_CLAMP_BANNER = 'LIMITS CLAMPED TO PORTABLE FLOOR';
export const HUD_CLAMP_BANNER_DEVICE = 'LIMITS CLAMPED BELOW CONFIGURED';

/** What main.ts's `getSample()` closure returns each refresh. */
export interface HudSample {
  fps: number;
  /** null ⇒ heap is unknown on this browser (non-Chromium) → "n/a". */
  heapUsedBytes: number | null;
  engineKind: string;
  caps: ResolvedDeviceCaps;
  /** Display-only extras (WebGL2 render/cubemap sizes) — no ceilings. */
  extraDisplayLimits?: Readonly<Record<string, number>>;
  /**
   * The loaded world's capability degradation report (undefined
   * when no world is loaded). Rendered as the HUD's capability line. DATA comes from the main bundle (session state); this chunk only
   * displays it.
   */
  capabilities?: CapabilityReport;
}

/**
 * Minimal element/host surfaces so unit tests run plain-object doubles under
 * the node Vitest environment (no jsdom) — the touchInput.ts pattern.
 */
export interface HudElement {
  setAttribute(name: string, value: string): void;
  /** `this`-typed so DOM's generic `appendChild<T extends Node>` satisfies it. */
  appendChild(child: this): unknown;
  remove(): void;
  readonly style: { cssText: string };
  textContent: string | null;
}

export interface HudHost<E extends HudElement = HudElement> {
  createElement(tagName: 'div'): E;
  body: { appendChild(child: E): unknown };
}

export interface DebugHudOptions {
  intervalMs?: number;
  /** Injectable timer seam for fake-timer unit tests. */
  setIntervalFn?: (handler: () => void, ms: number) => unknown;
  clearIntervalFn?: (handle: unknown) => void;
}

export interface DebugHud {
  dispose(): void;
}

/**
 * Human bytes: MiB with at most one decimal (whole values render without a
 * fraction); sub-MiB values (the 64 KiB UBO floor) render KiB.
 */
export function formatBytes(bytes: number): string {
  if (bytes >= 1_048_576) {
    const mib = bytes / 1_048_576;
    return `${Number.isInteger(mib) ? mib : Number(mib.toFixed(1))} MiB`;
  }
  const kib = bytes / 1_024;
  return `${Number.isInteger(kib) ? kib : Number(kib.toFixed(1))} KiB`;
}

/** MB with one decimal — the heap readout. */
export function formatHeapMB(bytes: number | null): string {
  return bytes === null ? 'n/a' : (bytes / 1_000_000).toFixed(1);
}

/** Byte-valued keys render MiB/KiB; dimension keys render the raw integer. */
function formatLimitValue(key: string, value: number): string {
  return key === 'maxTextureDimension2D' ? String(value) : formatBytes(value);
}

/** One limit line: `key actual X eff Y [CLAMPED→floor | CLAMPED→device]`. */
export function formatLimitLine(key: string, limit: ResolvedLimit): string {
  const actual = limit.actualKnown
    ? formatLimitValue(key, limit.actual as number)
    : 'n/a';
  const eff = formatLimitValue(key, limit.effective);
  const marker = limit.belowFloor
    ? ` ${HUD_CLAMP_MARKER}`
    : limit.clamped
      ? ` ${HUD_CLAMP_MARKER_DEVICE}`
      : '';
  return `${key} actual ${actual} eff ${eff}${marker}`;
}

const CONTAINER_CSS =
  'position:fixed;top:8px;left:8px;z-index:20;padding:8px 10px;' +
  'background:rgba(0,0,0,0.65);color:#8f8;border-radius:4px;' +
  'font:12px/1.5 ui-monospace,Consolas,monospace;white-space:pre;' +
  'pointer-events:none;user-select:none;-webkit-user-select:none;';

const BANNER_CSS = 'color:#f66;font-weight:bold;';

export function createDebugHud<E extends HudElement>(
  host: HudHost<E>,
  getSample: () => HudSample,
  options: DebugHudOptions = {},
): DebugHud {
  const intervalMs = options.intervalMs ?? HUD_UPDATE_INTERVAL_MS;
  const setIntervalFn =
    options.setIntervalFn ?? ((handler: () => void, ms: number) => setInterval(handler, ms));
  const clearIntervalFn =
    options.clearIntervalFn ?? ((handle: unknown) => clearInterval(handle as number));

  const container = host.createElement('div');
  container.setAttribute('data-webverse-hud', '1');
  // Dev-only visual, pointer-events:none — hidden from assistive tech.
  container.setAttribute('aria-hidden', 'true');
  container.style.cssText = CONTAINER_CSS;

  const line = (name: string, css?: string): E => {
    const el = host.createElement('div');
    el.setAttribute('data-webverse-hud-line', name);
    if (css !== undefined) el.style.cssText = css;
    container.appendChild(el);
    return el;
  };

  const engineLine = line('engine');
  const fpsLine = line('fps');
  const heapLine = line('heap');
  const bannerLine = line('banner', BANNER_CSS);
  // Capability line (rendered on every refresh: the report is
  // DYNAMIC, changing per world load, unlike the static limit lines below).
  const capabilitiesLine = line('capabilities');

  // Limit lines are created once from the initial sample (the caps shape is
  // static — resolved once at engine init); refreshes rewrite TEXT only.
  const initial = getSample();
  const limitLines: Array<[string, E]> = [];
  for (const key of Object.keys(initial.caps.limits)) {
    const el = host.createElement('div');
    el.setAttribute('data-webverse-hud-limit', key);
    container.appendChild(el);
    limitLines.push([key, el]);
  }
  const extraLines: Array<[string, E]> = [];
  for (const key of Object.keys(initial.extraDisplayLimits ?? {})) {
    const el = host.createElement('div');
    el.setAttribute('data-webverse-hud-extra', key);
    container.appendChild(el);
    extraLines.push([key, el]);
  }

  let updates = 0;
  const refresh = (): void => {
    const sample = getSample();
    engineLine.textContent = `engine ${sample.engineKind}`;
    fpsLine.textContent = `fps ${sample.fps.toFixed(1)}`;
    heapLine.textContent = `heap ${formatHeapMB(sample.heapUsedBytes)} / ${RESIDENT_MEMORY_BUDGET_MB} MB`;
    bannerLine.textContent = sample.caps.anyBelowFloor
      ? HUD_CLAMP_BANNER
      : sample.caps.anyClamped
        ? HUD_CLAMP_BANNER_DEVICE
        : '';
    container.setAttribute(
      'data-webverse-hud-clamped',
      sample.caps.anyClamped ? 'true' : 'false',
    );
    // Capability report: list every degraded
    // feature so nothing reads as dropped; the data-* attributes are the e2e's
    // deterministic assert.
    const report = sample.capabilities;
    if (report && report.gaps.length > 0) {
      capabilitiesLine.textContent =
        'degraded: ' + report.gaps.map((g) => `${g.feature}×${g.count}`).join(' ');
    } else {
      capabilitiesLine.textContent = 'capabilities OK';
    }
    container.setAttribute('data-webverse-hud-degraded', String(report?.degradedCount ?? 0));
    container.setAttribute('data-webverse-hud-unknown', String(report?.unknownCount ?? 0));
    for (const [key, el] of limitLines) {
      const limit = sample.caps.limits[key as keyof typeof sample.caps.limits];
      if (limit !== undefined) el.textContent = formatLimitLine(key, limit);
    }
    for (const [key, el] of extraLines) {
      const value = sample.extraDisplayLimits?.[key];
      // Babylon caps come straight off GL queries — a broken driver can hand
      // back undefined/NaN; render an honest "n/a", never "NaN" (review nit).
      el.textContent = `${key} ${typeof value === 'number' && Number.isFinite(value) ? value : 'n/a'}`;
    }
    updates += 1;
    container.setAttribute('data-webverse-hud-updates', String(updates));
  };

  refresh(); // first paint before the body attach — no flash of empty box
  host.body.appendChild(container);
  const handle = setIntervalFn(refresh, intervalMs);

  let disposed = false;
  return {
    dispose(): void {
      if (disposed) return;
      disposed = true;
      clearIntervalFn(handle);
      container.remove();
    },
  };
}
